#include <iostream>
#include <string>

class Person {
public:
    explicit Person(std::string n) : name(std::move(n)) {}
    const std::string& get() const { return name; }
private:
    std::string name;
};

class Student : public Person {
public:
    Student(std::string n, int m) : Person(std::move(n)), marks(m) {}
    int score() const { return marks; }
private:
    int marks;
};

int main() {
    Student s("Aman", 92);
    std::cout << s.get() << " " << s.score() << "\n";
    return 0;
}

