#include <iostream>
#include <vector>

int main() {
    std::vector<int> v{5, 2, 4, 1};
    for (std::size_t i = 1; i < v.size(); ++i) {
        int key = v[i];
        int j = static_cast<int>(i) - 1;
        while (j >= 0 && v[j] > key) {
            v[j + 1] = v[j];
            --j;
        }
        v[j + 1] = key;
    }
    for (int x : v) std::cout << x << " ";
    std::cout << "\n";
    return 0;
}

